async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  const blockSize = 65536;

  let state = initial;
  let physicalLine = 1;
  let recordIndex = 0;
  let reachedEOF = false;
  let closed = false;
  let fragments = [];
  let fragmentLength = 0;

  async function closeIterator() {
    if (closed) return;
    closed = true;

    const returnMethod = iterator.return;
    if (typeof returnMethod === "function") {
      await returnMethod.call(iterator);
    }
  }

  function append(fragment) {
    if (fragment.length !== 0) {
      fragments.push(fragment);
      fragmentLength += fragment.length;
    }
  }

  function takeLine() {
    if (fragments.length === 0) return "";
    if (fragments.length === 1) {
      const line = fragments[0];
      fragments = [];
      fragmentLength = 0;
      return line;
    }

    const line = fragments.join("");
    fragments = [];
    fragmentLength = 0;
    return line;
  }

  async function processLine(line) {
    if (line.trim().length === 0) return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    recordIndex += 1;
    state = result.state;
    return result.done;
  }

  async function consume(text) {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) {
        append(text.slice(start));
        return false;
      }

      append(text.slice(start, newline));
      const line = takeLine();

      if (await processLine(line)) return true;

      physicalLine += 1;
      start = newline + 1;
    }
  }

  try {
    while (true) {
      const step = await iterator.next();

      if (step.done) {
        reachedEOF = true;
        break;
      }

      const chunk = step.value;

      for (let offset = 0; offset < chunk.byteLength; offset += blockSize) {
        const block = chunk.subarray(
          offset,
          Math.min(offset + blockSize, chunk.byteLength)
        );
        const text = decoder.decode(block, { stream: true });

        if (await consume(text)) {
          await closeIterator();
          return state;
        }
      }
    }

    const tail = decoder.decode();

    if (await consume(tail)) {
      return state;
    }

    if (fragmentLength !== 0) {
      await processLine(takeLine());
    }

    return state;
  } catch (error) {
    try {
      await closeIterator();
    } catch {
      // Preserve the original read or reducer error.
    }
    throw error;
  }
}
